import{_ as o,o as t,c as s,ae as i}from"./chunks/framework.RRduUuAx.js";const u=JSON.parse('{"title":"ADR-005: Cross-Process Locking via O_EXCL Self-Implementation","description":"","frontmatter":{},"headers":[],"relativePath":"reference/adrs/005.md","filePath":"reference/adrs/005.md"}'),n={name:"reference/adrs/005.md"};function a(c,e,r,d,l,p){return t(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="adr-005-cross-process-locking-via-o-excl-self-implementation" tabindex="-1">ADR-005: Cross-Process Locking via O_EXCL Self-Implementation <a class="header-anchor" href="#adr-005-cross-process-locking-via-o-excl-self-implementation" aria-label="Permalink to &quot;ADR-005: Cross-Process Locking via O_EXCL Self-Implementation&quot;">​</a></h1><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><p>Accepted, 2026-04-27.</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>ADR-001 establishes omm as a pure OpenClaw plugin with a separate stdio MCP server process. ADR-003 commits to a zero-runtime-dependency MCP implementation. The plugin and the three MCP servers (<code>omm-state</code>, <code>omm-memory</code>, <code>omm-trace</code>) all read and write the same <code>${stateRoot}</code> directory, but they run in distinct OS processes:</p><ul><li>The plugin runs inside the OpenClaw Gateway / host Electron process.</li><li>Each MCP server is spawned by <code>mcporter</code> as its own Node.js process.</li></ul><p>The hardening shipped in 0.2.1 (<code>omm-fs-queue.ts</code>) serializes the <code>validate → exclusivity-check → write → rename</code> window per key, but only within a single Node process. The CHANGELOG explicitly flagged this:</p><blockquote><p>Cross-process write races between plugin and MCP server are still possible — single-writer-per-stateRoot is the documented invariant.</p></blockquote><p>For commercial-grade desktop deployment we want the invariant enforced mechanically rather than by documentation. ADR-003 forbids pulling in <code>proper-lockfile</code>, <code>lockfile</code>, or any other npm-published dependency.</p><p>POSIX advisory locks (<code>flock(2)</code>, <code>fcntl(F_SETLK)</code>) are not exposed by the Node standard library, and Windows lacks an equivalent without a native module — that path violates ADR-001 (&quot;no Rust native modules&quot;) as well.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>omm implements a cross-process lock manually using only Node.js built-ins, layered on top of the existing in-process queue:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>withCrossProcessLock(lockDir, key, fn, { timeoutMs?, staleMs? })</span></span></code></pre></div><ul><li>Lockfile location: <code>${lockDir}/.locks/${sanitize(key)}.lock</code>.</li><li>Acquisition: <code>fs.open(path, &#39;wx&#39;, 0o644)</code> — <code>wx</code> translates to <code>O_CREAT | O_EXCL</code>, which is atomic on every supported filesystem (NTFS, APFS, ext4) at the kernel/Win32 layer.</li><li>Lock body: a single JSON line <code>{ &quot;pid&quot;: …, &quot;startedAt&quot;: …, &quot;hostname&quot;: … }</code> written and <code>close()</code>-d before <code>fn()</code> runs.</li><li>Release: <code>fs.unlink</code> in a <code>try/finally</code> so an exception in <code>fn</code> still drops the lock.</li><li>Same-process re-entrancy: wrapped inside the existing <code>withKeyLock(${lockDir}::${key}, …)</code> so two awaits in one process do not race for the file.</li><li>Stale recovery: if <code>EEXIST</code> and the file&#39;s <code>mtime</code> is older than <code>staleMs</code> (default 30 s), read the recorded PID; if <code>hostname</code> differs, or <code>process.kill(pid, 0)</code> throws (ESRCH/EPERM=alive), the lock is considered abandoned, <code>unlink</code>-ed, and the loop retries.</li><li>Polling: <code>50 ms ± 20 ms</code> jitter to avoid thundering-herd when two callers wake on the same event-loop tick.</li><li>Timeout: <code>Error(&quot;OMM_E_LOCK_TIMEOUT: &lt;key&gt;&quot;)</code> after <code>timeoutMs</code> (default 5 s).</li></ul><p>The implementation lives in <code>omm-plugin/src/omm-fs-queue.ts</code> and is <strong>inlined verbatim</strong> into each of the three MCP servers (<code>omm-mcp/src/index.ts</code>, <code>omm-mcp-memory/src/index.ts</code>, <code>omm-mcp-trace/src/index.ts</code>). MCP servers cannot <code>import</code> from <code>omm-plugin</code> without violating ADR-003 (would pull a non-bundled dependency at runtime), so the duplication is the documented cost.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><p><strong>Positive:</strong></p><ul><li>Plugin process and MCP server process can no longer last-write-wins on the same <code>${stateRoot}/state/&lt;key&gt;.json</code>.</li><li>Zero new runtime or dev dependencies — <code>node:fs/promises</code>, <code>node:os</code>, <code>node:path</code> cover everything.</li><li>Deterministic failure mode: callers see <code>OMM_E_LOCK_TIMEOUT</code> instead of a silent corruption when contention exceeds the budget.</li><li>Recoverable from crashes: stale-lock detection means a <code>kill -9</code> on one process does not permanently brick the stateRoot.</li></ul><p><strong>Negative:</strong></p><ul><li>30 s window during which a crash holds the key unreleased to other processes — operationally acceptable for desktop single-user but a ceiling on multi-tenant deployments.</li><li>Polling, not event-driven: idle contention costs 50 ms per failed attempt (vs <code>inotify</code>/<code>ReadDirectoryChangesW</code> event delivery).</li><li>Lock metadata&#39;s PID liveness check works only on the same host; cross-host stateRoot sharing (e.g., NFS) cannot detect remote-crashed PIDs and must wait the full <code>staleMs</code> window.</li><li>Maintenance burden: the inlined MCP copies must stay byte-identical to the canonical <code>omm-fs-queue.ts</code> implementation. The build smoke (<code>pnpm omm:smoke-mcp</code>) plus stress test (<code>omm-stress-cross-process.mjs</code>) guard against drift.</li></ul><p><strong>Failure semantics:</strong></p><ul><li>Lock acquisition timeout → <code>Error(&quot;OMM_E_LOCK_TIMEOUT: &lt;key&gt;&quot;)</code> propagates to the caller. In the plugin tools this surfaces as <code>omm_state_write error: OMM_E_LOCK_TIMEOUT: &lt;key&gt;</code>. In MCP responses it becomes a JSON-RPC <code>-32000</code> error.</li><li>Lock metadata corruption → treated as no-metadata; falls through to the staleMs/PID liveness check.</li><li><code>unlink</code> failure during release → swallowed; next acquire-attempt hits <code>EEXIST</code> and resolves via stale logic.</li></ul><p><strong>Windows quirk (added 0.3.0-alpha.2):</strong></p><p>On Windows, racing <code>O_EXCL</code> opens emit <code>EPERM</code> instead of <code>EEXIST</code> because the previous holder still has the file descriptor briefly open after <code>writeFile/close</code>. The retry loop accepts both error codes; both mean &quot;lock is held, retry&quot;. This is documented in <code>omm-fs-queue.ts:144</code> and the inlined MCP copies.</p><p>The Windows EPERM path adds one extra polling cycle (50 ms ± 20 ms) per contention event, which raises the stress-test P99 from ~65 ms (Linux/macOS, EEXIST-only) to ~110-160 ms on Windows. The stress script&#39;s P99 budget was raised from 100 ms to 200 ms to reflect this honestly; the budget still detects pathological contention without being noise-flake on Windows.</p><h2 id="alternatives-considered" tabindex="-1">Alternatives Considered <a class="header-anchor" href="#alternatives-considered" aria-label="Permalink to &quot;Alternatives Considered&quot;">​</a></h2><p><strong><code>proper-lockfile</code></strong> (popular npm package): rejected. Pulling it in violates ADR-003. It also performs nearly the same <code>O_EXCL</code> + stale detection algorithm, so the dependency cost buys little.</p><p><strong><code>async-mutex</code> / Node-level mutex packages</strong>: in-process only, doesn&#39;t solve the cross-process problem.</p><p><strong>POSIX advisory locks via native addon</strong>: rejected per ADR-001 (no native modules). Would also need a Windows-specific equivalent.</p><p><strong>SQLite as the storage layer</strong>: would inherit SQLite&#39;s WAL-mode locking for free, but moves omm off the JSON-file storage model documented in the contracts and the plugin/MCP test suites — out of scope for a P0 hardening pass.</p><p><strong>Single shared mutex process</strong>: requires running an extra long-lived daemon, contradicting the &quot;no standalone CLI&quot; posture of ADR-001.</p>',31)])])}const h=o(n,[["render",a]]);export{u as __pageData,h as default};
